module benchmark/solution

import std/string (repeat, chars)

pure func digitRoman(n: int, one: string, five: string, ten: string) -> string =
  if n == 9 then "${one}${ten}"
  else if n == 4 then "${one}${five}"
  else if n >= 5 then "${five}${repeat(one, n - 5)}"
  else repeat(one, n)

export pure func toRoman(n: int) -> string ! {}
requires { n >= 1, n <= 3999 }
{
  let thousands = repeat("M", n / 1000);
  let hundreds = digitRoman((n / 100) % 10, "C", "D", "M");
  let tens = digitRoman((n / 10) % 10, "X", "L", "C");
  let ones = digitRoman(n % 10, "I", "V", "X");
  "${thousands}${hundreds}${tens}${ones}"
}

pure func romanValue(c: string) -> int =
  match c {
    "I" => 1,
    "V" => 5,
    "X" => 10,
    "L" => 50,
    "C" => 100,
    "D" => 500,
    "M" => 1000,
    _ => 0
  }

pure func parseRoman(cs: [string]) -> int =
  match cs {
    [] => 0,
    a :: rest => match rest {
      [] => romanValue(a),
      b :: tail =>
        if romanValue(a) < romanValue(b)
        then romanValue(b) - romanValue(a) + parseRoman(tail)
        else romanValue(a) + parseRoman(rest)
    }
  }

export pure func fromRoman(s: string) -> int = parseRoman(chars(s))

export pure func roundtrip(n: int) -> bool ! {}
requires { n >= 1, n <= 3999 }
ensures { result }
{
  fromRoman(toRoman(n)) == n
}

export pure func distinctEncoding(a: int, b: int) -> bool ! {}
requires { a >= 1, a <= 3999, b >= 1, b <= 3999 }
ensures { result }
{
  if a == b then true else toRoman(a) != toRoman(b)
}

export func main() -> () ! {IO} {
  println(toRoman(1994));
  println(toRoman(58));
  println(toRoman(3999));
  println(show(fromRoman("MCMXCIV")));
  println(show(fromRoman("LVIII")));
  println(show(roundtrip(2024)));
  println(show(distinctEncoding(4, 6)))
}
